/**
 * «مغامرة المجموعات التفاعلية» — أداة إدارة صف تحفيزية سحابية.
 * البوابة: تسجيل دخول + اشتراك مغامرة سارٍ (أو أدمِن). التخزين سحابي عبر /api/adventure.
 * لا ذكاء اصطناعي ولا رصيد — أداة مباشرة، بياناتها تُحفظ وتُستأنف بين الحصص والأجهزة.
 */
export const dynamic = 'force-dynamic';

const CSS = ":root{--gold:#F5C542;--rose:#F7A8B8;--mint:#7FD1C1;--cream:#FFF6E8;--ink:#2A1B3D;--plum:#5B3E8E;--accent:#F5C542}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;height:100%;overflow:hidden;background:#160E2A;font-family:'Tajawal',system-ui,sans-serif;color:var(--cream);user-select:none}\n.display{font-family:'Lalezar','Tajawal',sans-serif}\nbutton{font-family:'Tajawal',sans-serif;border:none;cursor:pointer;color:inherit}\n#app{position:fixed;inset:0;display:flex;flex-direction:column;color:var(--cream);background:radial-gradient(120% 90% at 50% 0%,#2A1B4A,#160E2A)}\n\n/* HUD */\n#hud{display:none;align-items:center;gap:7px;padding:calc(env(safe-area-inset-top) + 9px) 12px 8px;flex-wrap:wrap;z-index:6}\n.hbtn{background:rgba(20,12,38,.55);backdrop-filter:blur(8px);color:var(--cream);height:37px;padding:0 12px;border-radius:12px;font-size:13px;font-weight:800;box-shadow:inset 0 0 0 1px rgba(255,255,255,.16);display:inline-flex;align-items:center;gap:5px}\n.hbtn.gold{background:linear-gradient(160deg,#FFD976,#F0A93C);color:#4A2E06;box-shadow:none}\n.hbtn.pink{background:linear-gradient(160deg,#F9B6D0,#E97FB0);color:#5A1E3A;box-shadow:none}\n.htitle{font-size:18px;color:var(--gold);text-shadow:0 0 18px rgba(245,197,66,.5);display:flex;align-items:center;gap:6px}\n.hboard{background:rgba(20,12,38,.55);backdrop-filter:blur(8px);color:var(--cream);height:37px;padding:0 12px;border-radius:12px;font-size:13px;font-weight:800;box-shadow:inset 0 0 0 1px rgba(255,255,255,.16);display:inline-flex;align-items:center;gap:5px}\n.spacer{flex:1}\n.sync{font-size:11.5px;font-weight:800;color:var(--cream);padding:7px 11px;border-radius:999px;white-space:nowrap;background:rgba(20,12,38,.55);backdrop-filter:blur(8px);box-shadow:inset 0 0 0 1px rgba(255,255,255,.16)}\n\n/* LANES */\n#lanes{flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:9px;padding:4px 12px 12px}\n.lane{position:relative;flex:1;min-height:78px;border-radius:18px;overflow:hidden;background-size:cover;background-position:left center;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.12),0 6px 18px rgba(0,0,0,.35)}\n.lane.win{box-shadow:inset 0 0 0 2.5px var(--gold),0 0 28px rgba(245,197,66,.45)}\n.lane-veil{position:absolute;inset:0;background:linear-gradient(90deg,rgba(10,6,20,.05),rgba(10,6,20,.28) 60%,rgba(10,6,20,.05))}\n.lane-info{position:absolute;top:8px;right:12px;display:flex;align-items:center;gap:7px;text-shadow:0 2px 6px rgba(0,0,0,.6);z-index:3}\n.li-em{font-size:22px}\n.li-name{font-weight:900;font-size:15px}\n.li-city{font-size:11px;opacity:.9;font-weight:700;background:rgba(20,12,38,.4);padding:2px 8px;border-radius:999px}\n.li-pts{font-weight:900;font-size:13px;color:var(--gold);background:rgba(20,12,38,.45);padding:2px 9px;border-radius:999px}\n.road{position:absolute;inset:0;width:100%;height:100%;z-index:2;pointer-events:none}\n.road path{fill:none;stroke-linecap:round;vector-effect:non-scaling-stroke}\n.rd-base{stroke:rgba(255,255,255,.16);stroke-width:15}\n.rd-dot{stroke:rgba(255,255,255,.45);stroke-width:2.5;stroke-dasharray:1 12}\n.rd-done{stroke:var(--accent);stroke-width:6;filter:drop-shadow(0 0 5px var(--accent))}\n.avatar{position:absolute;width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:26px;\n background:radial-gradient(circle at 40% 35%,rgba(255,255,255,.9),rgba(255,255,255,.15));box-shadow:0 4px 14px rgba(0,0,0,.4),0 0 16px var(--accent);\n transform:translate(50%,-50%);transition:right .6s cubic-bezier(.2,.9,.3,1),top .6s cubic-bezier(.2,.9,.3,1);z-index:4}\n.avatar:active{filter:brightness(1.25)}\n.avatar .crown{position:absolute;top:-16px;font-size:17px}\n.avatar .rank{position:absolute;bottom:-8px;right:-6px;font-size:15px}\n.finish-flag{position:absolute;left:2%;font-size:16px;opacity:.85;z-index:3;transform:translateY(-50%)}\n.lane-toast{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.8);background:rgba(255,255,255,.95);color:var(--ink);font-weight:900;font-size:13px;padding:6px 14px;border-radius:999px;opacity:0;transition:.3s;z-index:5;white-space:nowrap;box-shadow:0 6px 18px rgba(0,0,0,.35)}\n.lane-toast.on{opacity:1;transform:translate(-50%,-50%) scale(1)}\n#lanes .empty{margin:auto;text-align:center;color:rgba(255,246,232,.7);font-weight:700;font-size:15px;line-height:2}\n\n/* DOCK */\n#dock{display:none;gap:10px;padding:10px 12px calc(env(safe-area-inset-bottom) + 12px);overflow-x:auto;scroll-snap-type:x mandatory;z-index:6}\n.gcard{scroll-snap-align:center;flex:0 0 auto;width:216px;background:rgba(20,12,38,.72);backdrop-filter:blur(10px);border-radius:18px;padding:11px 12px;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.14),0 8px 22px rgba(0,0,0,.4)}\n.gc-top{display:flex;align-items:center;gap:8px;margin-bottom:8px}\n.gc-em{font-size:24px}.gc-name{font-weight:900;font-size:14px;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.gc-edit{background:none;color:rgba(255,255,255,.5);font-size:13px}\n.gc-row{display:flex;gap:7px}\n.pm{height:44px;border-radius:13px;font-weight:900;display:flex;align-items:center;justify-content:center;font-size:15px}\n.pm.plus{flex:1;background:radial-gradient(circle at 35% 28%,#FFE9A8,#F0A93C);color:#4A2E06;box-shadow:0 5px 14px rgba(240,169,60,.4),inset 0 -4px 0 rgba(0,0,0,.12)}\n.pm.boost{width:52px;background:radial-gradient(circle at 35% 28%,#C6B0FF,#8A6BE0);color:#fff;box-shadow:0 5px 14px rgba(138,107,224,.4),inset 0 -4px 0 rgba(0,0,0,.12)}\n.pm.minus{width:44px;background:rgba(255,255,255,.08);color:#F7A8B8;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.16)}\n.pm:active{transform:translateY(2px)}\n.gc-step{text-align:center;font-size:11px;opacity:.7;margin-top:7px;font-weight:700}\n.addcard{scroll-snap-align:center;flex:0 0 auto;width:120px;border-radius:18px;background:rgba(255,255,255,.05);box-shadow:inset 0 0 0 2px rgba(255,255,255,.16);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;font-weight:800;font-size:13px}\n.addcard .ic{font-size:28px}\n\n/* setup + sheets */\n.layer{position:fixed;inset:0;z-index:20;display:none;flex-direction:column;align-items:center;justify-content:center;padding:22px;text-align:center;overflow-y:auto;color:var(--cream)}\n.layer.on{display:flex;animation:fade .35s both}\n@keyframes fade{from{opacity:0}to{opacity:1}}\n.veil{background:radial-gradient(120% 80% at 50% 110%,#7B5BB8,#4E357F 40%,#2B1B4A 75%,#160E2A)}\n.crown{font-size:56px;animation:fl 4s ease-in-out infinite}@keyframes fl{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}\n.setup-h1{font-size:clamp(28px,8vw,44px);color:var(--gold);margin:6px 0 4px;text-shadow:0 0 30px rgba(245,197,66,.5)}\n.setup-p{opacity:.85;line-height:1.8;margin:0 0 16px;max-width:420px;font-size:14px}\n.field{font-size:17px;font-weight:700;text-align:center;padding:13px;border-radius:16px;border:none;background:rgba(255,255,255,.92);color:var(--ink);width:min(300px,86vw);margin:6px 0 14px}\n.stage-row{display:flex;gap:9px;justify-content:center;margin:6px 0 18px}\n.stage-row button{width:60px;padding:11px 0;border-radius:14px;background:rgba(255,255,255,.08);color:var(--cream);font-weight:900;font-size:16px;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.16)}\n.stage-row button.on{background:linear-gradient(160deg,#FFD976,#F0A93C);color:#4A2E06;box-shadow:none}\n.btn{font-weight:800;font-size:16px;border-radius:999px;padding:13px 28px;background:linear-gradient(160deg,#FFD976,#F0A93C);color:#4A2E06;box-shadow:0 8px 20px rgba(0,0,0,.35),inset 0 -3px 0 rgba(0,0,0,.12)}\n.btn:active{transform:translateY(2px)}\n.btn.ghost{background:rgba(255,255,255,.1);color:var(--cream);box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.28)}\n.btn.wide{width:100%;margin-top:12px}\n.btn.danger{background:rgba(247,168,184,.14);color:#F7A8B8;box-shadow:inset 0 0 0 1.5px rgba(247,168,184,.4)}\n\n.sheet{position:fixed;inset:0;z-index:40;display:none;align-items:flex-end;justify-content:center;background:rgba(10,6,20,.6);backdrop-filter:blur(3px)}\n.sheet.on{display:flex}\n.sheet-inner{background:linear-gradient(180deg,#3A2666,#241640);color:var(--cream);width:100%;max-width:560px;border-radius:26px 26px 0 0;padding:20px 18px calc(env(safe-area-inset-bottom) + 22px);box-shadow:0 -12px 40px rgba(0,0,0,.5);animation:up .3s cubic-bezier(.2,.9,.3,1) both;max-height:90vh;overflow-y:auto}\n@keyframes up{from{transform:translateY(60px);opacity:.4}to{transform:none;opacity:1}}\n.sheet h3{font-size:19px;color:var(--gold);margin:0 0 4px;text-align:center}\n.sheet .msub{opacity:.85;color:var(--cream);font-size:13px;text-align:center;margin-bottom:14px}\n.reason-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.reason{padding:14px 8px;border-radius:16px;background:rgba(255,255,255,.07);box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.14);color:var(--cream);font-weight:800;font-size:14px;display:flex;flex-direction:column;align-items:center;gap:6px}\n.reason:active{transform:scale(.96);background:rgba(245,197,66,.16)}\n.reason .ri{font-size:23px}\n.city-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:4px 0 6px}\n.citycard{border-radius:14px;overflow:hidden;position:relative;height:66px;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.16);background-size:cover;background-position:left center}\n.citycard.sel{box-shadow:inset 0 0 0 2.5px var(--gold),0 0 18px rgba(245,197,66,.4)}\n.citycard b{position:absolute;bottom:0;left:0;right:0;background:linear-gradient(0deg,rgba(10,6,20,.8),transparent);color:#fff;font-size:12.5px;padding:12px 8px 5px;text-align:center;display:block}\n.emoji-pick{display:flex;flex-wrap:wrap;gap:7px;justify-content:center;margin:6px 0 12px}\n.emoji-pick button{font-size:23px;padding:7px;border-radius:11px;background:rgba(255,255,255,.07);box-shadow:inset 0 0 0 1.5px transparent}\n.emoji-pick button.on{box-shadow:inset 0 0 0 2px var(--gold);background:rgba(245,197,66,.14)}\n.slab{display:block;text-align:right;font-size:13px;font-weight:800;opacity:.85;margin:9px 2px 5px}\n.sinput{width:100%;padding:11px 13px;border-radius:13px;border:none;font-family:'Tajawal';font-size:15px;background:rgba(255,255,255,.94);color:var(--ink)}\n.board-item{display:flex;align-items:center;gap:10px;padding:12px;border-radius:14px;background:rgba(255,255,255,.06);box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.14);margin-bottom:9px}\n.board-item.active{box-shadow:inset 0 0 0 2px var(--gold);background:rgba(245,197,66,.1)}\n.board-item .bi-em{font-size:22px}.board-item .bi-main{flex:1;text-align:right}.board-item .bi-name{font-weight:900;font-size:15px}.board-item .bi-meta{font-size:12px;opacity:.7}.board-item .bi-del{color:#F7A8B8;font-size:15px;padding:6px}\n.log-list{max-height:56vh;overflow-y:auto}\n.log-row{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;background:rgba(255,255,255,.05);margin-bottom:7px}\n.log-row .lg-d{font-weight:900;font-size:15px;width:34px;text-align:center}\n.log-row .lg-d.up{color:var(--mint)}.log-row .lg-d.down{color:var(--rose)}\n.log-row .lg-main{flex:1;font-size:13.5px;font-weight:700}.log-row .lg-t{font-size:11px;opacity:.6}\n.mx{position:absolute;top:14px;left:16px;background:rgba(255,255,255,.1);color:var(--cream);width:32px;height:32px;border-radius:50%;font-size:14px}\n\n/* results */\n.res-card{display:flex;align-items:center;gap:11px;padding:12px 13px;border-radius:16px;margin-bottom:9px;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.16);background:rgba(255,255,255,.05)}\n.res-card.r1{background:linear-gradient(150deg,rgba(245,197,66,.28),rgba(245,197,66,.08));box-shadow:inset 0 0 0 2px var(--gold)}\n.res-medal{font-size:26px;width:34px;text-align:center}\n.res-em{font-size:26px}\n.res-main{flex:1}.res-name{font-weight:900;font-size:15px}.res-sub{font-size:12px;opacity:.75}\n.res-pts{font-weight:900;font-size:20px;color:var(--gold)}\n.res-total{text-align:center;background:rgba(255,255,255,.06);border-radius:14px;padding:11px;margin:6px 0 4px;font-weight:800;font-size:14px}\n.res-total b{color:var(--gold)}\n.res-note{font-size:11.5px;opacity:.7;text-align:center;line-height:1.9;margin-top:8px}\n\n#badgePop{position:fixed;top:22%;left:50%;transform:translate(-50%,-20px) scale(.8);z-index:60;opacity:0;transition:.4s;background:linear-gradient(160deg,#FFF3D0,#F3D06A);color:#4A2E06;border-radius:26px;padding:18px 28px;text-align:center;box-shadow:0 20px 50px rgba(0,0,0,.45);pointer-events:none;max-width:82vw}\n#badgePop.on{opacity:1;transform:translate(-50%,0) scale(1)}\n#badgePop .em{font-size:52px}#badgePop b{display:block;font-size:18px;margin-top:4px}#badgePop small{opacity:.82;font-size:13px}\n#winBanner{position:fixed;top:calc(env(safe-area-inset-top) + 56px);left:50%;transform:translateX(-50%);z-index:8;display:none;background:linear-gradient(160deg,#FFF3D0,#F3D06A);color:#4A2E06;font-weight:900;font-size:14px;padding:9px 20px;border-radius:999px;box-shadow:0 10px 30px rgba(0,0,0,.4);white-space:nowrap}\n#winBanner.on{display:block;animation:up .4s both}\n.confetti{position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:55}\n.cf{position:absolute;width:9px;height:14px;border-radius:2px;animation:fall linear forwards}\n@keyframes fall{to{transform:translateY(110vh) rotate(720deg);opacity:.2}}\n#toast{position:fixed;bottom:calc(env(safe-area-inset-bottom) + 116px);left:50%;transform:translateX(-50%);z-index:50;background:rgba(255,255,255,.95);color:var(--ink);font-size:13.5px;font-weight:800;padding:10px 18px;border-radius:16px;box-shadow:0 10px 26px rgba(0,0,0,.35);opacity:0;transition:.3s;max-width:80vw;text-align:center}\n#toast.on{opacity:1}\nbody.present #dock{display:none!important}\nbody.present #hud .hbtn:not(#presentBtn),body.present #hud .hboard{display:none}\nbody.present .lane{min-height:120px}\nbody.present .avatar{width:56px;height:56px;font-size:34px}";
